def parse_facts(raw: str):
    facts = []
    for line in raw.strip().splitlines():
        fields = line.split("||")
        if len(fields) != 7:
            raise ValueError(f"Expected seven fields, got {len(fields)}: {line}")
        topic, correct, wrong_a, wrong_b, wrong_c, explanation, keywords = fields
        facts.append({
            "topic": topic.strip(),
            "correct": correct.strip(),
            "wrong": [wrong_a.strip(), wrong_b.strip(), wrong_c.strip()],
            "explanation": explanation.strip(),
            "keywords": [item.strip() for item in keywords.split(",") if item.strip()],
        })
    if len(facts) < 10:
        raise ValueError(f"Expected at least 10 facts, got {len(facts)}")
    return facts


def question_source(existing):
    return {
        "label": existing["source"]["label"],
        "url": existing["source"]["url"],
        "note": "Original expansion question synthesized from the linked subject reference.",
    }


